import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*
import java.util.UUID

// 1. Data class Task
data class Task(
    val id: Long = UUID.randomUUID().mostSignificantBits,
    val title: String,
    val description: String = ""
)

// 2. Repository interface
interface TaskRepository {
    suspend fun loadTasks(): List<Task>
}

// 3. Repository implementation
class TaskRepositoryImpl(
    private val delayMs: Long = 1000
) : TaskRepository {
    override suspend fun loadTasks(): List<Task> {
        // Simuler un appel réseau
        delay(delayMs)
        return listOf(
            Task(title = "Acheter du pain", description = "Aller à la boulangerie"),
            Task(title = "Appeler le médecin", description = "Prendre rendez-vous"),
            Task(title = "Faire du sport", description = "Jogging de 30 minutes")
        )
    }
}

// 4 & 5. ViewModel with Flow
class TaskViewModel(
    private val taskRepository: TaskRepository = TaskRepositoryImpl()
) : ViewModel() {
    private val _tasks = MutableStateFlow<List<Task>>(emptyList())
    val tasks: StateFlow<List<Task>> = _tasks.asStateFlow()

    private val _loading = MutableStateFlow(false)
    val loading: StateFlow<Boolean> = _loading.asStateFlow()

    fun loadTasks() {
        viewModelScope.launch {
            _loading.value = true
            try {
                val tasks = taskRepository.loadTasks()
                _tasks.value = tasks
            } catch (e: Exception) {
                e.printStackTrace()
            } finally {
                _loading.value = false
            }
        }
    }
}

// 6. Composable qui observe le Flow
@Composable
fun TaskListScreen(
    viewModel: TaskViewModel = viewModel()
) {
    val tasks by viewModel.tasks.collectAsState()
    val loading by viewModel.loading.collectAsState()

    Column(modifier = Modifier.padding(16.dp)) {
        Text("Liste des tâches", style = MaterialTheme.typography.h5)
        Spacer(modifier = Modifier.height(16.dp))

        if (loading) {
            CircularProgressIndicator()
        } else {
            LazyColumn {
                items(tasks) { task ->
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(8.dp)
                    ) {
                        Column(modifier = Modifier.padding(16.dp)) {
                            Text(task.title, style = MaterialTheme.typography.body1)
                            Text(task.description, style = MaterialTheme.typography.body2)
                        }
                    }
                }
            }
        }
    }
}

