    override suspend fun loadTasks(): List<Task> {
        // Simulate network call
        delay(delayMs)
        return listOf(
            Task(title = "Buy bread", description = "Go to the bakery"),
            Task(title = "Call doctor", description = "Make appointment"),
            Task(title = "Work out", description = "30 minute jog")
        )
    }
}

// 4 & 5. ViewModel with Flow
class TaskViewModel(
    private val taskRepository: TaskRepository = TaskRepositoryImpl()
) : ViewModel() {
    private val _tasks = MutableStateFlow<List<Task>>(emptyList())
    val tasks: StateFlow<List<Task>> = _tasks.asStateFlow()

    private val _loading = MutableStateFlow(false)
    val loading: StateFlow<Boolean> = _loading.asStateFlow()

    fun loadTasks() {
        viewModelScope.launch {
            _loading.value = true
            try {
                val tasks = taskRepository.loadTasks()
                _tasks.value = tasks
            } catch (e: Exception) {
                e.printStackTrace()
            } finally {
                _loading.value = false
            }
        }
    }
}

// 6. Composable observing the Flow
@Composable
fun TaskListScreen(
    viewModel: TaskViewModel = viewModel()
) {
    val tasks by viewModel.tasks.collectAsState()
    val loading by viewModel.loading.collectAsState()

    Column(modifier = Modifier.padding(16.dp)) {
        Text("Task List", style = MaterialTheme.typography.h5)
        Spacer(modifier = Modifier.height(16.dp))

        if (loading) {
            CircularProgressIndicator()
        } else {
            LazyColumn {
                items(tasks) { task ->
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(8.dp)
                    ) {
                        Column(modifier = Modifier.padding(16.dp)) {
                            Text(task.title, style = MaterialTheme.typography.body1)
                            Text(task.description, style = MaterialTheme.typography.body2)
